static ssize_t do_rbd_remove(const char *buf, size_t count)
{
	struct rbd_device *rbd_dev = NULL;
	int dev_id;
	char opt_buf[6];
	bool force = false;
	int ret;

	if (!capable(CAP_SYS_ADMIN))
