		return -EINVAL;
	}
	if (opt_buf[0] != '\0') {
		if (!strcmp(opt_buf, "force")) {
			force = true;
		} else {
			pr_err("bad remove option at '%s'\n", opt_buf);
			return -EINVAL;
		}
	}

	ret = -ENOENT;
	spin_lock(&rbd_dev_list_lock);
	list_for_each_entry(rbd_dev, &rbd_dev_list, node) {
		if (rbd_dev->dev_id == dev_id) {
			ret = 0;
			break;
		}
